const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let session={},settings={},lessons=[],view='library',filter='all',search='',topic='',limit=100,doc=null,qi=0,photos=[],dirty=false,busy=false,pollTimer,toastTimer;
let phoneTopic='',phoneSearch='',phoneFilter='all',phoneReceipt=false,phoneLoading=false,phoneRouteRequest=0;
let searchExpanded=false,selectedFile=null,libraryOrder='recent';try{libraryOrder=localStorage.getItem('ybt-library-order')||'recent';}catch{}
let uploadTiming=null,recognitionTiming=null,uploadDocument=null;
let uploadForm={title:'',topic:'',text:''},uploadSession=null;
const phoneScreen=()=>matchMedia('(max-width:720px)').matches;
const statusLabel={ready:'可用于课堂',draft:'待校对',uploaded:'待识别',processing:'识别中',error:'识别失败',archived:'已收起',trashed:'回收站'};
async function api(path,options={}){const r=await fetch('/api'+path,{...options,headers:{'Content-Type':'application/json',...options.headers},body:options.body===undefined?undefined:JSON.stringify(options.body)});let d;try{d=await r.json();}catch{throw new Error('服务未返回有效响应，请检查网络或部署配置。');}if(!r.ok){if(r.status===401){session.authenticated=false;render();}throw new Error(d.error||'操作失败');}return d;}
function confirmDeletion(title){
 const dialog=$('delete-dialog');if(dialog.open)return Promise.resolve(false);
 $('delete-dialog-name').textContent=title;dialog.returnValue='';
 return new Promise(resolve=>{
  dialog.addEventListener('close',()=>resolve(dialog.returnValue==='delete'),{once:true});
  $('delete-dialog-cancel').onclick=()=>dialog.close('cancel');
  $('delete-dialog-confirm').onclick=()=>dialog.close('delete');
  dialog.showModal();
 });
}
function toast(msg,error=false){const el=$('toast');el.textContent=msg;el.className=error?'error':'';el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,error?8000:4000);}
async function run(fn){try{await fn();}catch(e){toast(e.message,true);}}
function nav(next){if(busy){toast('正在保存或识别，请完成后再切换页面。');return;}if(dirty&&!confirm('有尚未保存的修改，确定离开吗？'))return;dirty=false;view=next;location.hash=next;render();if(next==='library')run(refresh);}
const blankQuestion=()=>({label:String((doc?.questions.length||0)+1),stem:'',mode:'choice',questionType:'single_choice',blankLabel:'',groupId:'',options:'ABCD'.split('').map(key=>({key,text:''})),answer:'',accepted:[],invalid:true,reviewStatus:'needs_review',reason:'',context:[],enrichment:[],optionNotes:[],reviewed:false,section:'拍照练习'});
const date=s=>new Date(s).toLocaleDateString('zh-CN',{month:'2-digit',day:'2-digit'});
function shell(content){return `<div class="shell"><aside class="sidebar"><a class="logo" href="/"><img src="/icons/app-192.png" alt=""><strong>讲练</strong></a><div class="sidebar-caption">工作空间</div><nav class="nav"><button data-nav="library" class="${view==='library'?'active':''}"><b>▦</b>资料库</button><button data-nav="upload" class="${view==='upload'?'active':''}"><b>＋</b>上传</button><button data-nav="settings" class="${view==='settings'?'active':''}"><b>⚙</b>设置</button></nav><div class="sidebar-caption">资料位置</div><nav class="nav places">${[['all','全部资料'],['recent','最近使用'],['custom','我的新增'],['draft','待校对'],['ready','课堂资料'],['builtin','内置题库'],['archived','已收起'],['trash','回收站']].map(([f,t])=>`<button data-filter="${f}" class="${view==='library'&&filter===f?'active':''}"><b>${f==='archived'?'▱':'▤'}</b>${t}</button>`).join('')}</nav><div class="sidebar-bottom"><img src="/icons/app-192.png" alt=""><span>课堂工作台</span>${session.localAdmin?'<button data-action="phone" title="手机连接">手机连接</button>':'<button data-action="logout" title="退出">退出</button>'}</div></aside><main class="main ${view==='library'?'library-main':''}">${content}</main></div>`;}
function loginHTML(){return `<div class="login"><section class="panel auth-panel"><img class="auth-brand" src="/icons/app-192.png" alt="讲练"><h1>手机扫码登录</h1><img id="login-qr" class="login-qr" alt="用已绑定手机扫描此登录二维码" hidden><div id="login-code" class="auth-code"></div><p id="login-status" role="status">正在生成二维码…</p><div id="login-browser-actions" class="login-browser-actions" hidden><a id="login-open-browser" class="primary auth-link" target="_blank" rel="noopener noreferrer">在已绑定浏览器中授权</a><button id="login-copy-link" type="button">复制授权链接</button></div><button id="login-refresh" type="button">刷新二维码</button><p class="auth-instruction">用已绑定手机的浏览器扫码，核对授权码后确认</p></section></div>`;}
function libraryHTML(){return `<section class="finder-library"><div class="toolbar"><div class="library-actions"><button data-nav="upload" title="上传资料">上传资料</button><button data-action="import-json">导入 JSON</button><button data-action="refresh">刷新</button></div><div class="search-control"><button type="button" class="icon-button" id="search-toggle" data-action="toggle-search" title="搜索资料" aria-label="搜索资料" aria-controls="library-search-field" aria-expanded="${searchExpanded}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg></button><label class="search-field" id="library-search-field" ${searchExpanded?'':'hidden'}><input class="search" id="search" type="search" placeholder=" " value="${esc(search)}" aria-label="搜索资料"></label></div><details class="sort-menu" id="library-sort-menu"><summary class="icon-button" title="资料排序" aria-label="资料排序"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" aria-hidden="true"><path d="M3 6h14M3 12h10M3 18h6m10-8v11m-3-3 3 3 3-3"/></svg></summary><div class="sort-options" role="menu" aria-label="排序方式">${[['recent','最近使用'],['updated','最近修改'],['title','名称']].map(([v,t])=>`<button type="button" data-sort="${v}" role="menuitemradio" aria-checked="${v===libraryOrder}"><span>${t}</span><span class="sort-check" aria-hidden="true">✓</span></button>`).join('')}</div></details></div><div id="library-results"></div><input type="file" id="json-file" class="file-input" accept="application/json,.json"></section>`;}
function libraryDetailHTML(selected){const stamp=t=>t?new Date(t).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):'未使用';return selected?`<img class="detail-app-icon" src="/icons/app-192.png" alt=""><h2>${esc(selected.title)}</h2><span class="tag ${esc(selected.status)}">${statusLabel[selected.status]||'待校对'}</span><dl><dt>专题</dt><dd>${esc(selected.topic)}</dd><dt>题目</dt><dd>${selected.count}</dd><dt>最近使用</dt><dd>${stamp(selected.lastUsedAt)}</dd><dt>修改时间</dt><dd>${stamp(selected.updatedAt)}</dd><dt>来源</dt><dd>${selected.sourceType==='builtin'?'内置题库':selected.sourceType==='photo'?'拍照资料':'我的资料'}</dd></dl><div class="detail-actions">${selected.status==='trashed'?`<button data-untrash="${esc(selected.id)}" title="恢复资料" aria-label="恢复资料">恢复资料</button>`:`${selected.count?`<button data-play="${esc(selected.id)}" title="开始讲解">开始讲解</button>`:''}<button data-edit="${esc(selected.id)}" title="打开整理">打开整理</button><button data-trash="${esc(selected.id)}" title="删除资料" aria-label="删除资料">删除</button>`}</div>`:'<p>选择一份资料</p>';}
function renderCards(){
 if(phoneScreen()){if($('phone-library-results'))$('phone-library-results').innerHTML=phoneLibraryRowsHTML(lessons,{topic:phoneTopic,search:phoneSearch,filter:phoneFilter});return;}
 const foldersScroll=document.querySelector('.finder-folders')?.scrollTop||0,filesScroll=document.querySelector('.finder-files')?.scrollTop||0;
 const all=filterLibrary(lessons,{filter,search});const groups=libraryGroups(all);if(topic&&!groups.some(g=>g.topic===topic))topic='';const list=sortLibrary(all.filter(d=>!topic||d.topic===topic),libraryOrder);
 if(!list.some(d=>d.id===selectedFile))selectedFile=list[0]?.id||null;const selected=list.find(d=>d.id===selectedFile);const stamp=t=>t?new Date(t).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):'未使用';
 const folder=(name,value,count)=>`<button class="folder-row ${topic===value?'selected':''}" data-topic="${esc(value)}" aria-pressed="${topic===value}"><svg class="folder-symbol" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M3 7h7l2 2h9v11H3z M3 7V4h7l2 3"/></svg><span>${esc(name)}</span><small>${count}</small><span>›</span></button>`;
 $('library-results').innerHTML=`<div class="column-browser"><section class="finder-column"><header>分类</header><div class="finder-folders">${folder('全部专题','',all.length)}${groups.map(g=>folder(g.topic,g.topic,g.count)).join('')}</div></section><section class="finder-column"><header><span>${esc(topic||'全部资料')}</span><span>${list.length} 份</span></header><div class="finder-files">${list.map(d=>`<div class="finder-file ${d.id===selectedFile?'selected':''}" tabindex="0" data-file="${esc(d.id)}" aria-label="${esc(d.title)}"><span class="document-symbol">▤</span><div><strong>${esc(d.title)}</strong><span>${d.count} 题 · ${libraryOrder==='recent'?stamp(d.lastUsedAt):date(d.updatedAt)}</span></div><div class="file-row-actions">${d.status==='trashed'?`<button data-untrash="${esc(d.id)}" title="恢复资料" aria-label="恢复资料">恢复</button>`:`${d.count?`<button data-play="${esc(d.id)}" title="开始讲解">开始讲解</button>`:''}<button data-edit="${esc(d.id)}" title="${d.sourceType==='builtin'?'复制编辑':'打开整理'}">打开整理</button><button data-trash="${esc(d.id)}" title="删除资料" aria-label="删除资料">删除</button>`}</div><span class="file-chevron">›</span></div>`).join('')||'<div class="empty">没有符合条件的资料</div>'}</div></section><section class="finder-column detail-column"><header>资料详情</header><div class="finder-detail">${libraryDetailHTML(selected)}</div></section></div><div class="finder-status">${topic?esc(topic)+' / ':''}${list.length} 份资料 · ${list.reduce((n,d)=>n+d.count,0)} 题</div>`;
 document.querySelector('.finder-folders').scrollTop=foldersScroll;document.querySelector('.finder-files').scrollTop=filesScroll;
}
function uploadHTML(){return `<div class="centered-page upload-page"><div class="section-title upload-heading"><div><div class="eyebrow">CAPTURE A NEW LESSON</div><h1>上传题目，开始备课</h1><p class="muted">上传原题，整理后校对，再用于课堂演示。</p></div></div><div class="split"><section class="panel"><div class="row"><div><label for="upload-title">资料名称</label><input id="upload-title" value="${esc(uploadForm.title)}" placeholder="例如：周三课堂 · 动词短语巩固"></div><div><label for="upload-topic">专题</label><input id="upload-topic" value="${esc(uploadForm.topic)}" placeholder="例如：动词与短语" list="topics"><datalist id="topics">${[...new Set(lessons.map(d=>d.topic))].map(t=>`<option value="${esc(t)}">`).join('')}</datalist></div></div><div class="upload-zone"><div class="upload-icon">▧</div><h3>选择照片或文档</h3><button class="primary" data-action="camera">◉ 手机拍照</button><button data-action="gallery">选择照片</button><button data-action="document" title="上传 DOC、DOCX、Markdown、TXT 文档（每份2MB以内）">上传文档</button><p>每份最多 10 张，按题目顺序排列。支持 JPG / PNG / WebP。<br>文档支持 DOC / DOCX / MD / TXT，每份不超过2MB。<br>长文本会自动分批整理；照片上传前自动压缩，请确保文字清楚。</p></div><input id="camera-file" type="file" accept="image/*" capture="environment" class="file-input"><input id="gallery-file" type="file" accept="image/*" multiple class="file-input"><input id="document-file" type="file" accept=".doc,.docx,.md,.markdown,.txt" class="file-input"><div id="document-list"></div><div class="photos" id="photo-list"></div><label for="upload-text">补充文字 <span class="muted">（可选，也可只粘贴题目）</span></label><textarea id="upload-text" placeholder="可粘贴已有 OCR 原文，或补充照片外的阅读材料。不要在这里填写模型密钥。">${esc(uploadForm.text)}</textarea>${!session.configured?'<p class="notice" style="margin-top:20px">尚未配置视觉模型。资料仍可保存，完成模型设置后可继续整理。</p>':''}<div class="row" style="margin-top:22px"><button class="primary" data-action="upload" ${busy?'disabled':''}>${busy?'正在保存与整理…':'保存并整理 →'}</button><button data-action="save-upload" ${busy?'disabled':''}>只保存，稍后识别</button></div><div id="upload-progress"></div></section><aside class="panel" style="background:#fbfcf7"><div class="eyebrow">A SMALL WORKFLOW, A READY LESSON</div><h2>从手机到电子白板</h2><div class="step"><span class="step-num">1</span><div><h3>上传原题</h3><p>可选择照片、Word 文档或粘贴文字；拍照请确保文字清楚。</p></div></div><div class="step"><span class="step-num">2</span><div><h3>识别并补充解析</h3><p>保留原文，整理题干、选项、答案和逐项解析；看不清的内容标为待确认。</p></div></div><div class="step"><span class="step-num">3</span><div><h3>对照原始资料校对</h3><p>你可以修改每道题，并决定何时保存为课堂资料。</p></div></div><div class="step"><span class="step-num">4</span><div><h3>打开，开始讲解</h3><p>全屏、字号、解析弹窗、题号导航和翻页笔沿用现有操作。</p></div></div><button data-action="demo" style="width:100%;margin-top:20px">先体验编辑与演示</button><p class="inline-note">体验使用明确的示例题目，不上传图片，也不调用模型。</p></aside></div></div>`;}
function documentList(){const el=$('document-list');if(el)el.innerHTML=uploadDocument?`<div class="document-upload"><span>▤ ${esc(uploadDocument.name)}</span><button data-action="remove-document" aria-label="移除文档" title="移除文档">×</button></div>`:'';}
function photoList(){documentList();if(!$('photo-list'))return;if($('phone-upload-action')){$('phone-upload-action').hidden=!photos.length&&!uploadDocument;const count=document.querySelector('.phone-sequence');if(count)count.textContent=(uploadDocument?'1 份文档'+(photos.length?' · ':''):'')+(photos.length?photos.length+' 张图片':'');} $('photo-list').innerHTML=photos.map((p,i)=>`<div class="photo"><img src="${p.dataUrl}" alt="第${i+1}张照片预览"><small>${i+1}. ${esc(p.name)} · ${Math.round(p.size/1024)}KB</small><button data-photo-up="${i}" ${i===0?'disabled':''}>←</button><button data-photo-down="${i}" ${i===photos.length-1?'disabled':''}>→</button><button data-photo-remove="${i}">移除</button></div>`).join('');}
function settingsHTML(){return `<div class="settings-grid centered-page"><h1 class="page-title">设置</h1>${themeSettingsHTML()}<details class="panel model-settings"><summary>模型服务配置</summary><form id="settings-form">${!settings.localAdmin?'<div class="notice">请在运行服务的电脑上打开本页修改。Vercel 部署后通过环境变量设置密钥。</div>':''}<label for="model-base">API 基础地址</label><input id="model-base" required placeholder="服务商提供的 HTTPS 基础地址，通常以 /v1 结尾" value="${esc(settings.baseUrl)}" ${!settings.localAdmin?'disabled':''}><p class="inline-note">填写基础地址，不要重复添加 /chat/completions。国内视觉模型选择“兼容 Chat 接口”。</p><label for="model-id">视觉模型名称</label><input id="model-id" required placeholder="填写服务商控制台中的模型 ID（须支持图片输入）" value="${esc(settings.model)}" ${!settings.localAdmin?'disabled':''}><label for="model-key">API Key</label><input id="model-key" type="password" autocomplete="new-password" placeholder="${settings.hasKey?'已保存；留空保留现有密钥':'仅保存在本机服务端'}" ${!settings.localAdmin?'disabled':''}><div class="row"><div><label for="model-mode">接口格式</label><select id="model-mode" ${!settings.localAdmin?'disabled':''}><option value="chat" ${settings.apiMode==='chat'?'selected':''}>OpenAI 兼容 Chat（国内视觉模型）</option><option value="responses" ${settings.apiMode==='responses'?'selected':''}>OpenAI Responses</option></select></div></div><label class="check"><input id="json-mode" type="checkbox" ${settings.jsonMode?'checked':''} ${!settings.localAdmin?'disabled':''}>服务商支持 JSON Mode 时启用（不确定可关闭）</label><p class="inline-note">关闭时仍要求 JSON 输出，并由服务端校验；长文本自动分批整理，输出截断时自动缩小批次；原始资料与已完成进度保持保存。</p>${settings.localAdmin?'<button class="primary" style="margin-top:23px">保存配置</button>':''}<p class="inline-note">当前存储：${esc(settings.storage)}。已保存配置不代表服务商连通性已验证；首次识别将进行真实调用。</p></form></details></div>`;}
function timingHTML(){const t=doc?.modelInfo?.timings;if(!t)return "";const f=n=>(Number(n||0)/1000).toFixed(1)+" 秒";return `<details class="timing-panel"><summary>识别整理 ${f(recognitionTiming?.lessonId===doc.id?recognitionTiming.requestMs:t.totalMs)}</summary><p>模型：${esc(doc.modelInfo.model)}</p><dl><dt>准备与读取资料</dt><dd>${f(t.prepareMs)}</dd><dt>读取照片</dt><dd>${f(t.imageReadMs)}</dd><dt>模型请求与返回</dt><dd>${f(t.modelMs)}</dd><dt>校验整理</dt><dd>${f(t.normalizeMs)}</dd>${recognitionTiming?.lessonId===doc.id?`<dt>保存结果</dt><dd>${f(recognitionTiming.resultSaveMs)}</dd>`:""}</dl>${uploadTiming?.lessonId===doc.id?`<p>本次传图与入库 ${(uploadTiming.ms/1000).toFixed(1)} 秒</p>`:""}</details>`;}
function editorHTML(){
 if(!doc)return '<div class="loading">正在打开资料…</div>';const q=doc.questions[qi];
 return `<div class="editor-top"><div><div class="eyebrow">REVIEW BEFORE CLASS</div><h1>${esc(doc.title)}</h1><span class="tag ${esc(doc.status)}">${statusLabel[doc.status]}</span> <span id="save-state" class="muted">${dirty?'有未保存修改':'已保存'} · ${doc.questions.length} 题</span></div><div class="editor-actions">${doc.questions.length?`<button data-action="export">导出 JSON</button><button data-action="preview">预览演示 ↗</button>`:''}<button data-action="save" ${busy?'disabled':''}>保存草稿</button><button class="primary" data-action="publish" ${busy||!q?'disabled':''}>保存为课堂资料</button></div></div>${timingHTML()}${doc.error?`<div class="notice">${esc(doc.error)}<br>原始资料与已完成批次已保存。可以修改设置后继续整理，或手动添加题目。</div>`:''}${['uploaded','error','processing'].includes(doc.status)?`<div class="notice">${doc.status==='processing'?'该资料正在识别。若上一次连接中断，等待约3分钟后可重新尝试。':'资料已保存，点击下方按钮开始识别与整理。'} <button data-action="recognize" ${busy?'disabled':''}>${busy?'识别中，请稍候…':'开始 / 重试识别'}</button>${busy?'<div class="busybar"></div>':''}</div>`:''}<div class="editor-grid"><aside class="panel source-panel"><details open><summary>原始资料与识别原文</summary>${(doc.documents||[]).map(d=>`<p><a href="${esc(d.url)}">▤ ${esc(d.name)}</a></p>`).join('')}${(doc.images||[]).map((p,i)=>`<p class="inline-note">上传第 ${i+1} 张</p><a href="${esc(p.url)}" target="_blank" rel="noopener"><img src="${esc(p.url)}" alt="第${i+1}张原图，点击放大"></a>`).join('')||'<p class="muted">这份资料没有上传原图。</p>'}<label for="ocr-text">识别原文 / 补充原文</label><textarea id="ocr-text" ${busy?'disabled':''}>${esc(doc.ocrText||doc.inputText)}</textarea><p class="inline-note">原文与模型补充的解析分开保存，可对照照片修正。点击图片可在新页放大。</p></details>${doc.pageOrder?.length?`<div class="notice">建议阅读页序：${doc.pageOrder.map(n=>'第'+n+'张').join(' → ')}<br>${esc(doc.orderNote)}</div>`:''}<label for="edit-title">资料名称</label><input id="edit-title" value="${esc(doc.title)}"><label for="edit-topic">专题</label><input id="edit-topic" value="${esc(doc.topic)}"><label class="check"><input id="allow-pending" type="checkbox">保留待确认题用于讲解（不计分）</label><button data-action="delete-document" class="ghost" style="margin-top:20px" title="删除资料" aria-label="删除资料">删除资料</button><button data-action="archive" class="ghost" style="margin-top:20px">${doc.status==='archived'?'恢复到草稿':'收起这份资料'}</button></aside><section class="panel"><div class="question-header"><h3>逐题校对</h3><button data-action="sort-questions" ${busy?'disabled':''}>按原题号排序</button><button data-action="repair-materials" ${busy?'disabled':''}>补全篇章</button><button data-action="add-question">＋ 添加题目</button></div>${phoneScreen()?phoneQuestionPickerHTML(doc,qi):`<div class="question-strip" role="navigation" aria-label="按原顺序选择校对题目">${doc.questions.map((q,i)=>`<button data-question="${i}" class="${qi===i?'active':''} ${q.invalid?'needs':''}">${esc(q.label)}${q.reviewed?' ✓':q.invalid?' ?':''}</button>`).join('')}</div>`}${q?questionHTML(q):'<div class="empty">还没有题目。完成识别，或点击“添加题目”手动整理。</div>'}${q?'<button class="ghost" data-action="review-all" style="margin-top:20px">我已核对全部题目，统一标记 ✓</button>':''}</section></div>`;
}
function questionHTML(q){return `<div class="row" style="margin-bottom:14px"><button data-action="question-up" ${qi===0?'disabled':''}>← 前移本题</button><button data-action="question-down" ${qi===doc.questions.length-1?'disabled':''}>后移本题 →</button></div>${q.sourcePages?.length?`<p class="inline-note">本题来源：上传的第 ${q.sourcePages.join('、')} 张图片</p>`:''}<div class="row"><div class="narrow"><label for="q-label">原题号</label><input id="q-label" data-q="label" value="${esc(q.label)}"></div><div><label for="q-mode">课堂展示方式</label><select id="q-mode" data-q="mode">${[['choice','单项选择'],['multi','多项选择'],['input','展示问答'],['self','开放作答 / 写作'],['study','讲解卡']].map(([v,t])=>`<option value="${v}" ${q.mode===v?'selected':''}>${t}</option>`).join('')}</select></div><div><label for="q-answer">${q.mode==='choice'?'考试建议答案':'参考答案'}</label>${q.mode==='choice'?`<select id="q-answer" data-q="answer"><option value="">待确认</option>${q.answer&&q.answer!=='待确认'&&!q.options.some(o=>o.key===q.answer)?`<option value="${esc(q.answer)}" selected>${esc(q.answer)}（原答案，待核对）</option>`:''}${q.options.map(o=>`<option value="${o.key}" ${q.answer===o.key?'selected':''}>${o.key}</option>`).join('')}</select>`:`<input id="q-answer" data-q="answer" value="${esc(q.answer==='待确认'?'':q.answer)}">`}</div></div><div class="row"><div><label for="q-type">具体题型</label><select id="q-type">${Object.entries(QUESTION_TYPES).map(([v,t])=>`<option value="${v}" ${inferQuestionType(q)===v?'selected':''}>${t.label}</option>`).join('')}</select></div>${needsMaterial(q)?`<div><label for="q-blank-label">原始空号 / 小题号</label><input id="q-blank-label" value="${esc(q.blankLabel||q.label)}"></div><div><label for="q-group">同篇材料编号</label><input id="q-group" value="${esc(q.groupId||'')}" placeholder="例如：阅读A / 七选五1"></div>`:''}</div>${['sentence_completion','cloze','matching'].includes(inferQuestionType(q))?'<p class="inline-note">每个空或匹配项单独一题，阅读材料和共享选项需完整保留；七选五每空保留全部 A—G 选项。</p>':''}${q.mode==='multi'?'<p class="inline-note">多选答案用逗号分隔，如 A,C；课堂中选齐后点击“确认选择”。</p>':''}${hasMaterial(q.context)||needsMaterial(q)?`<section class="material-editor">${!needsMaterial(q)?'<details><summary>附加材料（可选）</summary>':''}<h3>${needsMaterial(q)?'完整篇章 / 共享题干':'附加材料'}</h3>${needsMaterial(q)?'<p class="inline-note">演示左侧显示完整材料，右侧显示当前小题。同组篇章修改会同步到该组题目。</p>':'<p class="inline-note">此题按独立题展示。原有附加材料保留在这里，不作为阅读篇章分栏显示。</p>'}${!hasMaterial(q.context)?'<p class="notice material-warning">此题尚未关联篇章。可点击“补全篇章”，从已保存原文或照片中重新提取。</p>':''}<label for="q-context">${needsMaterial(q)?'篇章全文（含标题、说明、全部段落与空格）':'附加文字（可选）'}</label><textarea id="q-context">${esc((q.context||[]).filter(b=>b.type!=='table').map(b=>b.text).join('\n\n'))}</textarea>${q.context?.some(b=>b.type==='table')?'<div class="material-tables">'+q.context.filter(b=>b.type==='table').map(b=>'<table>'+b.rows.map(row=>'<tr>'+row.map(c=>'<td>'+esc(c)+'</td>').join('')+'</tr>').join('')+'</table>').join('')+'<p class="inline-note">原有表格保留；本输入框编辑文字段落。</p>':''}${!needsMaterial(q)?'</details>':''}</section>`:''}<label for="q-stem">题干</label><textarea id="q-stem" data-q="stem" style="min-height:130px">${esc(q.stem)}</textarea>${['choice','multi'].includes(q.mode)?`<label>选项</label>${q.options.map((o,i)=>`<div class="option-edit"><strong>${o.key}</strong><textarea aria-label="选项 ${o.key}" data-option="${i}">${esc(o.text)}</textarea><button data-remove-option="${i}" title="移除选项">×</button></div>`).join('')}<button data-action="add-option" class="ghost">＋ 增加选项</button>`:''}<label for="q-reason">详细解析</label><textarea id="q-reason" data-q="reason" style="min-height:150px">${esc(q.reason)}</textarea><label for="q-note">严谨性 / 待确认说明</label><textarea id="q-note" data-q="examNote">${esc(q.examNote)}</textarea><label class="check"><input id="q-invalid" type="checkbox" ${q.invalid?'checked':''}>本题仍需确认，不进行对错计分</label><label class="check"><input id="q-reviewed" type="checkbox" ${q.reviewed?'checked':''}>已对照原图核对本题内容及答案</label><details style="margin-top:22px"><summary>逐项解析（${q.optionNotes?.length||0}）</summary>${(q.optionNotes||[]).map((o,i)=>`<label>${esc(o.key)} · ${esc(o.text)}</label><textarea data-option-note="${i}">${esc(o.reason)}</textarea>`).join('')||'<p class="inline-note">模型可生成全部选项解析。手动资料可通过下方“更多字段”补充。</p>'}</details><details style="margin-top:22px"><summary>规则与例句（${q.enrichment.length}）</summary>${q.enrichment.map((e,i)=>`<section class="rule-edit">${[['phrase','短语 / 规则'],['meaning','词义 / 规则说明'],['usage','用法'],['example','英文例句'],['translation','中文翻译'],['contrast','易错辨析']].map(([k,t])=>`<label>${t}</label>${k==='phrase'?`<input data-rule="${i}" data-field="${k}" value="${esc(e[k])}">`:`<textarea data-rule="${i}" data-field="${k}">${esc(e[k])}</textarea>`}`).join('')}<button class="ghost" data-remove-rule="${i}">移除此条</button></section>`).join('')}<button data-action="add-rule">＋ 添加规则 / 例句</button></details><details style="margin-top:22px"><summary>更多字段</summary><label for="q-extra">逐项解析 JSON</label><textarea id="q-extra" spellcheck="false">${esc(JSON.stringify(q.optionNotes||[],null,2))}</textarea><button data-action="apply-extra">应用逐项解析 JSON</button></details><button data-action="remove-question" class="ghost" style="color:#996a56;margin-top:26px">移除本题</button>`;}
function phoneCaptureHTML(){return `<main class="phone-capture"><header><a class="phone-brand" href="/">讲练 <small>拍照备课</small></a><span>手机上传</span></header><div class="phone-heading"><h1>上传资料，留给课堂。</h1><p>支持照片和 Word 文档，长文本自动分批整理。</p></div><button class="capture-main" data-action="camera" ${busy?'disabled':''}><svg viewBox="0 0 48 48" aria-hidden="true"><path d="M7 14h8l4-6h10l4 6h8v26H7z" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linejoin="round"/><circle cx="24" cy="26" r="8" fill="none" stroke="currentColor" stroke-width="2.5"/></svg><strong>拍照上传</strong><span>打开相机，可连续添加多张</span></button><button class="capture-gallery" data-action="gallery" ${busy?'disabled':''}><span>▧</span><div><strong>上传本地图片</strong><small>相册多选，每份最多10张</small></div><b>＋</b></button><button class="capture-gallery" data-action="document" ${busy?'disabled':''}><span>▤</span><div><strong>上传文档</strong><small>DOC / DOCX / MD / TXT · 每份2MB以内</small></div><b>＋</b></button><input id="document-file" type="file" accept=".doc,.docx,.md,.markdown,.txt" class="file-input"><div id="document-list"></div><input id="camera-file" type="file" accept="image/*" capture="environment" class="file-input"><input id="gallery-file" type="file" accept="image/*" multiple class="file-input"><input id="upload-title" type="hidden" value="${esc(uploadForm.title||'手机上传 · '+new Date().toLocaleString('zh-CN'))}"><input id="upload-topic" type="hidden" value="${esc(uploadForm.topic||'英语练习')}"><textarea id="upload-text" hidden>${esc(uploadForm.text)}</textarea><div class="photos phone-photos" id="photo-list"></div><div id="phone-upload-action" ${photos.length||uploadDocument?'':'hidden'}><p class="phone-sequence">已选 ${photos.length} 张 · 可用左右箭头调整预览顺序</p><button class="phone-send" data-action="upload" ${busy?'disabled':''}>${busy?'正在上传…':uploadSession?'继续上传 →':'上传并整理 →'}</button></div><div id="upload-progress"></div><p class="phone-foot">上传后可在“资料演示”中浏览、校对和编辑。${session.configured?'':'<br>模型尚未配置，现在也可以先上传保存。'}</p></main>`;}
function phoneReceiptHTML(){return `<main class="phone-capture"><header><span class="phone-brand">讲练 <small>拍照备课</small></span><span>已保存</span></header><section class="phone-receipt"><div class="receipt-icon">${busy?'⋯':'✓'}</div><h1>${busy?'正在识别与排序':doc.status==='draft'?'已整理成草稿':'资料已保存'}</h1><p>${busy?'原始资料已保存，模型正在分批整理题目。':doc.status==='error'?'整理暂未完成，资料与进度已保存，可继续重试。':'可直接在手机浏览与编辑，也可回到电脑继续。'}</p><strong>${esc(doc.title)}</strong><span>${doc.documents?.length?doc.documents.length+' 份文档 · ':''}${doc.images?.length||0} 张图片${doc.questions.length?' · '+doc.questions.length+' 题':''}</span><p id="save-state" class="muted">${busy?'请稍候…':'无需再次传到电脑'}</p>${busy?'<div class="busybar"></div>':''}${doc.orderNote?'<p class="phone-order">'+esc(doc.orderNote)+'</p>':''}${!busy&&['uploaded','error','processing'].includes(doc.status)?'<button class="phone-send" data-action="recognize">继续整理</button>':''}<button class="phone-send" data-phone-route="lesson/${esc(doc.id)}" ${busy?'disabled':''}>浏览与编辑这份资料</button><button class="phone-send" data-nav="upload" ${busy?'disabled':''}>继续上传其他资料</button></section></main>`;}
function phoneEditorHTML(){
 const body=editorHTML().replace('<aside class="panel source-panel">','<details class="panel source-panel"><summary>资料信息与原始文件</summary>').replace('</aside><section class="panel">','</details><section class="panel">').replace('<details open>','<details>');
 return `<main class="phone-page phone-editor">${phoneHeaderHTML('编辑题目','lesson/'+encodeURIComponent(doc.id),doc.sourceType==='builtin'?'内置题库将复制后编辑':'修改后请保存草稿')}${body}</main>`;
}
function render(){
 if(!session.authenticated){clearInterval(pollTimer);$('app').innerHTML=loginHTML();mountLogin(async()=>{await boot();const back=new URL(location.href).searchParams.get('return');if(back?.startsWith('/player.html?'))location.href=back;});return;}
 stopLogin();
 if(phoneScreen()){
  let content,active='library';
  if(view==='upload'){content=phoneCaptureHTML();active='upload';}
  else if(view==='editor'&&doc){content=phoneReceipt?phoneReceiptHTML():phoneEditorHTML();active=phoneReceipt?'upload':'library';}
  else if(view==='lesson'&&doc)content=phoneLessonHTML(doc);
  else if(view==='reader'&&doc)content=phoneReaderHTML(doc,qi);
  else content=phoneLibraryHTML(lessons,{topic:phoneTopic,search:phoneSearch,filter:phoneFilter});
  $('app').innerHTML=phoneFrameHTML(content,active)+(phoneLoading?'<div class="phone-loading" role="status">正在打开资料…</div>':'');
  if(view==='upload')photoList();
 }else{
  if(['lesson','reader'].includes(view))view='library';
  $('app').innerHTML=shell(view==='library'?libraryHTML():view==='upload'?uploadHTML():view==='settings'?settingsHTML():editorHTML());
  if(view==='library')renderCards();if(view==='upload')photoList();
 }
 if(view==='editor'&&busy)document.querySelectorAll('.editor-grid input,.editor-grid textarea,.editor-grid select,.editor-grid button,.phone-edit-picker select,.editor-actions button').forEach(el=>el.disabled=true);
}
function currentPhoneRoute(){
 if(view==='library')return 'library'+(phoneTopic?'/'+encodeURIComponent(phoneTopic):'');
 if(view==='reader')return 'read/'+encodeURIComponent(doc.id)+'/'+qi;
 if(['lesson','editor'].includes(view)&&doc)return view+'/'+encodeURIComponent(doc.id);
 return view==='upload'?'upload':'library';
}
function phoneNavigate(target){
 if(busy){toast('正在保存或整理，请完成后再切换页面。');return;}
 if(location.hash.slice(1)===target)return;
 location.hash=target;
}
async function applyPhoneRoute(target,force=false){
 const previous=currentPhoneRoute();if(!force&&target===previous){if(phoneLoading){++phoneRouteRequest;phoneLoading=false;render();}return;}
 if(busy){location.replace('#'+previous);toast('正在保存或整理，请完成后再切换页面。');return;}
 if(dirty&&!confirm('有尚未保存的修改，确定离开吗？')){location.replace('#'+previous);return;}
 const request=++phoneRouteRequest;
 const [kind,rawId,rawIndex]=target.split('/');
 let value;try{value=decodeURIComponent(rawId||'');}catch{toast('页面地址无效。',true);return;}
 if(['lesson','read','editor'].includes(kind)&&value){
  phoneLoading=true;render();let routed=false;
  try{
   let incoming=doc;
   if(kind==='editor'&&builtInId(value)){incoming=hydrateMaterials((await api('/lessons/'+encodeURIComponent(value)+'/copy',{method:'POST',body:{}})).lesson);}
   else if(doc?.id!==value||kind==='lesson'||force)incoming=hydrateMaterials((await api('/lessons/'+encodeURIComponent(value))).lesson);
   if(request!==phoneRouteRequest)return;
   if(incoming.status==='trashed')throw new Error('这份资料已在回收站，请先在电脑端恢复。');
   dirty=false;doc=incoming;phoneReceipt=false;qi=kind==='read'?Math.max(0,Math.min(Math.trunc(Number(rawIndex))||0,doc.questions.length-1)):0;view=kind==='read'?'reader':kind;routed=true;
   if(incoming.id!==value)history.replaceState(null,'','#editor/'+encodeURIComponent(incoming.id));
   run(()=>api('/lessons/'+encodeURIComponent(doc.id)+'/use',{method:'POST',body:{}}));
  }catch(e){if(request===phoneRouteRequest){history.replaceState(null,'','#'+previous);toast(e.message,true);}}
  finally{if(request===phoneRouteRequest){phoneLoading=false;render();if(routed)window.scrollTo?.(0,0);}}
 }else{
  dirty=false;phoneLoading=false;phoneReceipt=false;view=kind==='upload'?'upload':'library';phoneTopic=view==='library'&&kind==='library'?value:'';render();window.scrollTo?.(0,0);
  if(view==='library')await refresh();
 }
}
async function refresh(){lessons=(await api('/lessons')).lessons;if(view==='library')renderCards();}
async function openDoc(id,copy=false){if(dirty&&!confirm('离开将放弃未保存的修改，继续吗？'))return;const data=copy?await api('/lessons/'+id+'/copy',{method:'POST',body:{}}):await api('/lessons/'+id);dirty=false;phoneReceipt=false;doc=hydrateMaterials(data.lesson);run(()=>api('/lessons/'+doc.id+'/use',{method:'POST',body:{}}));qi=0;view='editor';location.hash='editor/'+doc.id;render();if(phoneScreen())window.scrollTo?.(0,0);}
function markDirty(){dirty=true;const s=$('save-state');if(s)s.textContent='有未保存修改 · '+doc.questions.length+' 题';}
function syncNotes(){for(const q of doc.questions)q.optionNotes=(q.optionNotes||[]).map(n=>({...n,text:q.options.find(o=>o.key===n.key)?.text||n.text}));}
async function saveDraft(){const activeLabel=doc.questions[qi]?.label;syncNotes();const data=await api('/lessons/'+doc.id,{method:'PUT',body:{version:doc.version,lesson:compactMaterials(doc)}});doc=hydrateMaterials(data.lesson);qi=Math.max(0,doc.questions.findIndex(q=>q.label===activeLabel));dirty=false;return doc;}
async function publish(){const allow=$('allow-pending')?.checked||false;busy=true;try{await saveDraft();const data=await api('/lessons/'+doc.id+'/publish',{method:'POST',body:{version:doc.version,allowPending:allow}});doc=hydrateMaterials(data.lesson);dirty=false;await refresh();toast('已保存为课堂资料，白板可打开讲解。');}finally{busy=false;render();}}
async function processDoc(){
 busy=true;render();let elapsed=0,progress=doc.recognitionProgress;
 const timer=setInterval(()=>{elapsed++;const s=$('save-state');if(s)s.textContent=(progress?'分批整理：已完成 '+progress.completed+' 批，剩余 '+progress.remaining+' 批':'模型识别与整理中')+' · '+elapsed+' 秒';},1000);
 try{let result;do{result=await api('/lessons/'+doc.id+'/recognize',{method:'POST',body:{}});doc=hydrateMaterials(result.lesson);progress=result.progress;}while(result.pending);
 recognitionTiming={lessonId:doc.id,...result.timings};dirty=false;qi=0;run(refresh);toast('整理完成，请对照原始资料逐题校对。');
 }catch(e){doc=hydrateMaterials((await api('/lessons/'+doc.id)).lesson);throw e;}finally{clearInterval(timer);busy=false;render();}
}
async function repairMaterials(){
 if(busy)return;if(dirty)await saveDraft();busy=true;render();let progress=doc.materialRepairProgress;
 const timer=setInterval(()=>{const s=$('save-state');if(s)s.textContent='正在补全篇章'+(progress?' · 已完成 '+progress.completed+' 批，剩余 '+progress.remaining+' 批':'');},1000);
 try{let result;do{result=await api('/lessons/'+doc.id+'/materials',{method:'POST',body:{version:doc.version}});doc=hydrateMaterials(result.lesson);progress=result.progress;}while(result.pending);dirty=false;toast('篇章已补全，原有小题和答案已保留，请核对材料。');}
 catch(e){doc=hydrateMaterials((await api('/lessons/'+doc.id)).lesson);throw e;}finally{clearInterval(timer);busy=false;render();}
}
async function compress(file){if(file.size>25*1024*1024)throw new Error('单张原图超过25MB，请先裁剪。');const image=new Image(),url=URL.createObjectURL(file);try{await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(new Error('无法读取这张照片。若是HEIC，请转为JPG后上传。'));image.src=url;});if(!image.naturalWidth||image.naturalWidth*image.naturalHeight>60000000)throw new Error('照片尺寸过大，请先裁剪。');let scale=Math.min(1,1900/Math.max(image.naturalWidth,image.naturalHeight));const canvas=document.createElement('canvas');canvas.width=Math.round(image.naturalWidth*scale);canvas.height=Math.round(image.naturalHeight*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);let quality=.86,dataUrl=canvas.toDataURL('image/jpeg',quality);while(dataUrl.length>1100000&&quality>.35){quality-=.1;dataUrl=canvas.toDataURL('image/jpeg',quality);}const size=Math.ceil((dataUrl.length-dataUrl.indexOf(',')-1)*.75);if(size>1000000)throw new Error('压缩后图片仍过大，请裁剪为单页后重试。');return {name:file.name||'拍照.jpg',dataUrl,size};}finally{URL.revokeObjectURL(url);}}
async function upload(start=true){
 if(busy)return;if(!photos.length&&!uploadDocument&&!$('upload-text').value.trim())throw new Error('请选择照片、文档或粘贴原文。');
 const uploadStarted=performance.now();
 const payload={title:$('upload-title').value,topic:$('upload-topic').value,text:$('upload-text').value,document:uploadDocument,images:photos.map(({name,dataUrl})=>({name,dataUrl}))};
 busy=true;document.querySelectorAll('[data-action="upload"],[data-action="save-upload"]').forEach(b=>b.disabled=true);
 const progress=(n,total)=>{if($('upload-progress'))$('upload-progress').innerHTML='<div class="progress-box">正在保存资料 '+n+' / '+total+'<div class="busybar"></div></div>';};
 try{
  let saved;if(uploadSession){saved=(await api('/lessons/'+uploadSession.id)).lesson;}else{progress(1,payload.images.length||1);let initialCount=0,initialBytes=payload.document?4000000:0;for(const image of payload.images){const n=image.dataUrl.length;if((initialCount||payload.document)&&initialBytes+n>3000000)break;initialBytes+=n;initialCount++;}saved=(await api('/imports',{method:'POST',body:{...payload,images:payload.images.slice(0,initialCount)}})).lesson;uploadSession={id:saved.id};}
  for(let i=saved.images.length;i<payload.images.length;i++){progress(i+1,payload.images.length);saved=(await api('/lessons/'+saved.id+'/images',{method:'POST',body:{version:saved.version,image:payload.images[i]}})).lesson;}
  uploadTiming={lessonId:saved.id,ms:Math.round(performance.now()-uploadStarted)};recognitionTiming=null;doc=saved;phoneReceipt=phoneScreen();photos=[];uploadDocument=null;uploadSession=null;uploadForm={title:'',topic:'',text:''};view='editor';location.hash='editor/'+doc.id;dirty=false;qi=0;busy=false;render();
  if(start&&session.configured)await processDoc();else toast('资料已保存，可以稍后继续识别。');
 }catch(e){if(view==='upload'&&uploadSession)e.message+=' 已上传的资料保留，保持当前选择并再次点击即可继续上传。';throw e;}
 finally{busy=false;if(view==='upload')render();}
}
async function demo(){const q=[{label:'1',stem:'You should ____ smoking, ____ you will get ill.',mode:'choice',options:[{key:'A',text:'go on; so'},{key:'B',text:'give up; or'},{key:'C',text:'stop; so'},{key:'D',text:'give in; unless'}],answer:'B',reason:'give up doing 表停止、戒除；or 表否则。C 的 stop smoking 虽能表达戒烟，但 so 把结果关系说反。',context:[],enrichment:[{phrase:'give up doing',meaning:'放弃做；戒除',usage:'后接名词或动名词，代词宾语放中间。',example:'He gave up smoking last year.',translation:'他去年戒烟了。',contrast:'give in 表屈服，不等于戒除。'}],invalid:false,reviewed:false},{label:'2',stem:'We have lived here ____ five years.',mode:'choice',options:[{key:'A',text:'for'},{key:'B',text:'since'},{key:'C',text:'at'},{key:'D',text:'on'}],answer:'A',reason:'five years 为一段时间，用 for；since 后接起点。',context:[],enrichment:[],invalid:false,reviewed:false}];const data=await api('/import-json',{method:'POST',body:{lesson:{title:'体验示例 · 校对到课堂',topic:'操作体验',ocrText:'这是预置示例，不是照片识别结果。',notes:['操作体验，不调用模型。'],questions:q}}});doc=hydrateMaterials(data.lesson);qi=0;view='editor';dirty=false;location.hash='editor/'+doc.id;render();}
async function phone(){settings=await api('/settings');$('phone-content').innerHTML='<p>手机和电脑连接同一 Wi-Fi 后，可打开以下地址：</p>'+(settings.phoneUrls||[]).map(u=>`<code>${esc(u)}</code>`).join('')+'<p>首次绑定手机，请在运行服务的电脑上执行：</p><code>npm run phone:pair</code><p>用自己的手机扫码并确认绑定。公网部署使用同一份云端数据库生成绑定二维码。</p>';$('phone-dialog').showModal();}
$('phone-close').onclick=()=>$('phone-dialog').close();
document.addEventListener('submit',e=>{e.preventDefault();run(async()=>{if(e.target.id==='settings-form'){const values={baseUrl:$('model-base').value,model:$('model-id').value,apiKey:$('model-key').value,apiMode:$('model-mode').value,jsonMode:$('json-mode').checked};settings=await api('/settings',{method:'POST',body:values});session.configured=settings.hasKey;render();toast('配置已保存；识别时将调用真实模型服务。');}});});
document.addEventListener('input',e=>{
 const el=e.target;if(el.id==='phone-library-search'){phoneSearch=el.value;renderCards();return;}if(view==='upload'&&['upload-title','upload-topic','upload-text'].includes(el.id)){uploadForm[el.id.slice(7)]=el.value;return;}if(el.id==='search'){search=el.value;limit=100;renderCards();return;}
 if(view!=='editor'||!doc)return;const q=doc.questions[qi];
 if(el.id==='q-blank-label'&&q){q.blankLabel=el.value;q.reviewed=false;}else if(el.id==='q-group'&&q){q.groupId=el.value;q.materialDetached=true;const material=doc.materials?.find(m=>m.id===el.value);if(material)q.context=material.context;q.reviewed=false;}else if(el.id==='edit-title')doc.title=el.value;else if(el.id==='edit-topic')doc.topic=el.value;else if(el.id==='ocr-text')doc.ocrText=el.value;else if(q&&el.dataset.q){q[el.dataset.q]=el.value;q.reviewed=false;if(el.dataset.q==='answer'){q.invalid=!el.value;q.reviewStatus=q.invalid?'needs_review':'ok';}}
 else if(q&&el.dataset.option!==undefined){q.options[+el.dataset.option].text=el.value;q.reviewed=false;}
 else if(q&&el.dataset.optionNote!==undefined){q.optionNotes[+el.dataset.optionNote].reason=el.value;q.reviewed=false;}
 else if(q&&el.dataset.rule!==undefined){q.enrichment[+el.dataset.rule][el.dataset.field]=el.value;q.reviewed=false;}
 else if(q&&el.id==='q-context'){updateSharedMaterial(doc,q,[...(q.context||[]).filter(b=>b.type==='table'),...el.value.split(/\n\s*\n/).filter(Boolean).map(text=>({type:'p',text}))]);q.reviewed=false;}
 else return;markDirty();
});
document.addEventListener('change',e=>run(async()=>{
 const el=e.target;
 if(el.id==='phone-edit-question'){if(!busy){qi=+el.value;render();}return;}
 if(busy&&['camera-file','gallery-file','document-file'].includes(el.id))return;
 if(el.id==='document-file'){const file=el.files[0];el.value='';if(!file)return;if(!/\.(doc|docx|md|markdown|txt)$/i.test(file.name))throw new Error('支持 DOC、DOCX、Markdown 和 TXT 文档。');if(file.size>2097152)throw new Error('文档需小于2MB，请按章节拆分。');const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(new Error('文档读取失败。'));reader.readAsDataURL(file);});uploadDocument={name:file.name,base64};uploadSession=null;photoList();return;}
 if(['camera-file','gallery-file'].includes(el.id)){const files=[...el.files];if(photos.length+files.length>10)throw new Error('每份资料最多10张照片，请分批上传。');uploadSession=null;for(const file of files)photos.push(await compress(file));el.value='';photoList();}
 if(el.id==='json-file'&&el.files[0]){if(el.files[0].size>3000000)throw new Error('JSON文件超过3MB，请分份导入。');let data;try{data=JSON.parse(await el.files[0].text());}catch{throw new Error('JSON文件格式不正确。');}const r=await api('/import-json',{method:'POST',body:{lesson:data.lesson||data}});doc=hydrateMaterials(r.lesson);qi=0;dirty=false;view='editor';location.hash='editor/'+doc.id;render();}

 const q=doc?.questions[qi];if(view==='editor'&&q){if(el.id==='q-invalid'){q.invalid=el.checked;q.reviewStatus=el.checked?'needs_review':'ok';q.reviewed=false;markDirty();}if(el.id==='q-reviewed'){q.reviewed=el.checked;markDirty();}if(el.id==='q-type'){selectQuestionType(q,el.value);markDirty();render();}if(el.id==='q-mode'){selectQuestionType(q,({choice:'single_choice',multi:'multiple_choice',input:'short_answer',self:'writing',study:'study'})[q.mode]);markDirty();render();}}
}));
document.addEventListener('click',e=>run(async()=>{
 const b=e.target.closest('button,a[data-action]');if(!b||b.disabled)return;
 if(b.dataset.phoneRoute!==undefined){phoneNavigate(b.dataset.phoneRoute);return;}
 if(b.dataset.phoneFilter){phoneFilter=b.dataset.phoneFilter;document.querySelectorAll('[data-phone-filter]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.phoneFilter===phoneFilter)));renderCards();return;}
 if(b.dataset.phoneEdit){if(busy||phoneLoading)return;const questionIndex=Number(b.dataset.phoneEditQuestion)||0;const label=doc?.questions[questionIndex]?.label;busy=true;phoneLoading=true;render();try{await openDoc(b.dataset.phoneEdit,builtInId(b.dataset.phoneEdit));qi=Math.max(0,doc.questions.findIndex(q=>q.label===label));}finally{busy=false;phoneLoading=false;render();}return;}
 if(b.dataset.phoneQuestion!==undefined){if(!busy){qi=Math.max(0,Math.min(+b.dataset.phoneQuestion,doc.questions.length-1));render();document.querySelector('.phone-edit-picker')?.scrollIntoView({block:'start'});}return;}
 if(busy&&view==='editor')return;
if(busy&&(['camera','gallery','document','remove-document'].includes(b.dataset.action)||b.dataset.photoRemove!==undefined||b.dataset.photoUp!==undefined||b.dataset.photoDown!==undefined))return;
 if(b.dataset.sort){libraryOrder=b.dataset.sort;try{localStorage.setItem('ybt-library-order',libraryOrder);}catch{}document.querySelectorAll('[data-sort]').forEach(el=>el.setAttribute('aria-checked',String(el.dataset.sort===libraryOrder)));$('library-sort-menu').open=false;$('library-sort-menu').querySelector('summary').focus();renderCards();return;}
 if(b.dataset.topic!==undefined){topic=b.dataset.topic;selectedFile=null;renderCards();return;}
 if(b.dataset.nav){nav(b.dataset.nav);return;}if(b.dataset.filter){if(dirty&&!confirm('有未保存修改，确定离开吗？'))return;dirty=false;filter=b.dataset.filter;limit=100;view='library';location.hash='library';render();run(refresh);return;}
 if(b.dataset.trash||b.dataset.untrash){const id=b.dataset.trash||b.dataset.untrash,item=lessons.find(x=>x.id===id);if(!item)throw new Error('资料不存在，请刷新后重试。');if(b.dataset.trash&&!await confirmDeletion(item.title))return;await api('/lessons/'+id+'/'+(b.dataset.trash?'trash':'untrash'),{method:'POST',body:{version:item.version}});selectedFile=null;await refresh();renderCards();toast(b.dataset.trash?'已移入回收站。':'资料已恢复。');return;}
 if(b.dataset.play){window.open('/player.html?id='+encodeURIComponent(b.dataset.play),'_blank','noopener');return;}
 if(b.dataset.edit){await openDoc(b.dataset.edit,builtInId(b.dataset.edit));return;}
 if(b.dataset.photoRemove!==undefined){uploadSession=null;photos.splice(+b.dataset.photoRemove,1);photoList();return;}
 if(b.dataset.photoDown!==undefined){uploadSession=null;const i=+b.dataset.photoDown;[photos[i],photos[i+1]]=[photos[i+1],photos[i]];photoList();return;}
 if(b.dataset.photoUp!==undefined){uploadSession=null;const i=+b.dataset.photoUp;[photos[i-1],photos[i]]=[photos[i],photos[i-1]];photoList();return;}
 if(b.dataset.question!==undefined){qi=+b.dataset.question;render();return;}
 const q=doc?.questions[qi];
 if(b.dataset.removeOption!==undefined){q.options.splice(+b.dataset.removeOption,1);q.reviewed=false;markDirty();render();return;}
 if(b.dataset.removeRule!==undefined){q.enrichment.splice(+b.dataset.removeRule,1);q.reviewed=false;markDirty();render();return;}
 switch(b.dataset.action){
 case 'toggle-search':searchExpanded=!searchExpanded;$('library-search-field').hidden=!searchExpanded;$('search-toggle').setAttribute('aria-expanded',String(searchExpanded));if(searchExpanded)$('search').focus();else if(search){search='';$('search').value='';renderCards();}break;
 case 'phone':await phone();break;
 case 'logout':await api('/logout',{method:'POST',body:{}});session.authenticated=false;render();break;
 case 'refresh':await refresh();toast('资料库已更新。');break;
 case 'more':limit+=100;renderCards();break;
 case 'camera':$('camera-file').click();break;
 case 'gallery':$('gallery-file').click();break;
 case 'document':$('document-file').click();break;
 case 'remove-document':uploadDocument=null;uploadSession=null;photoList();break;
 case 'upload':await upload(true);break;
 case 'save-upload':await upload(false);break;
 case 'demo':await demo();break;
 case 'import-json':$('json-file').click();break;
 case 'repair-materials':await repairMaterials();break;
 case 'recognize':if(dirty)throw new Error('请先保存修改，或重新打开资料后识别。');await processDoc();break;
 case 'save':if(busy)return;busy=true;render();try{await saveDraft();toast('草稿已保存。');}finally{busy=false;render();}break;
 case 'publish':await publish();break;
 case 'preview':if(dirty)throw new Error('请先保存草稿，再打开演示预览。');window.open('/player.html?id='+doc.id,'_blank','noopener');break;
 case 'export':if(dirty)throw new Error('请先保存修改再导出。');location.href='/api/lessons/'+doc.id+'/export';break;
 case 'sort-questions':{const label=q?.label;doc.questions=orderQuestions(doc.questions);doc.questionOrder='number';qi=Math.max(0,doc.questions.findIndex(q=>q.label===label));markDirty();render();break;}
 case 'question-up':if(qi>0){[doc.questions[qi-1],doc.questions[qi]]=[doc.questions[qi],doc.questions[qi-1]];qi--;doc.questionOrder='manual';markDirty();render();}break;
 case 'question-down':if(qi<doc.questions.length-1){[doc.questions[qi],doc.questions[qi+1]]=[doc.questions[qi+1],doc.questions[qi]];qi++;doc.questionOrder='manual';markDirty();render();}break;
 case 'add-question':if(!doc.questions.length)doc.status='draft';doc.questions.push(blankQuestion());qi=doc.questions.length-1;markDirty();render();break;
 case 'remove-question':if(confirm('从当前草稿移除此题？保存前可重新打开资料恢复。')){doc.questions.splice(qi,1);qi=Math.max(0,qi-1);markDirty();render();}break;
 case 'add-option':{const key=OPTION_KEYS.split('').find(k=>!q.options.some(o=>o.key===k));if(!key)throw new Error('最多26个选项。');q.options.push({key,text:''});q.reviewed=false;markDirty();render();break;}
 case 'add-rule':q.enrichment.push({phrase:'',meaning:'',usage:'',example:'',translation:'',contrast:''});q.reviewed=false;markDirty();render();break;
 case 'apply-extra':{let notes;try{notes=JSON.parse($('q-extra').value);}catch{throw new Error('逐项解析JSON格式不正确。');}if(!Array.isArray(notes)||notes.some(n=>!n||typeof n!=='object'))throw new Error('请输入解析对象数组。');q.optionNotes=notes;q.reviewed=false;markDirty();render();toast('逐项解析已应用，记得保存。');break;}
 case 'review-all':doc.questions.forEach(x=>x.reviewed=true);markDirty();render();toast('已标记全部题目，请保存。');break;
 case 'delete-document':if(dirty)throw new Error('请先保存修改，再删除资料。');if(!await confirmDeletion(doc.title))break;await api('/lessons/'+doc.id+'/trash',{method:'POST',body:{version:doc.version}});dirty=false;doc=null;view='library';filter='all';location.hash='library';render();await refresh();toast('已移入回收站。');break;
 case 'archive':if(dirty)throw new Error('请先保存修改再收起资料。');doc=(await api('/lessons/'+doc.id+'/'+(doc.status==='archived'?'restore':'archive'),{method:'POST',body:{version:doc.version}})).lesson;await refresh();render();toast('已更新资料状态。');break;
 }
}));
function builtInId(id){return id.startsWith('builtin-');}
window.addEventListener('hashchange',()=>run(async()=>{if(!session.authenticated)return;if(phoneScreen()){await applyPhoneRoute(location.hash.slice(1)||'upload');return;}const target=location.hash.slice(1)||'library',current=view==='editor'?'editor/'+doc?.id:view;if(target===current)return;if(busy){location.hash=current;toast('识别中，请完成后再切换页面。');return;}if(target.startsWith('editor/')){await openDoc(target.slice(7));return;}if(dirty&&!confirm('有尚未保存的修改，确定离开吗？')){location.hash=current;return;}dirty=false;view=['library','upload','settings'].includes(target)?target:'library';render();if(view==='library')await refresh();}));
matchMedia('(max-width:720px)').addEventListener('change',()=>render());
window.addEventListener('beforeunload',e=>{if(dirty||busy){e.preventDefault();e.returnValue='';}});
async function boot(){session=await api('/session');if(!session.authenticated){render();return;}settings=await api('/settings');lessons=(await api('/lessons')).lessons;const hash=location.hash.slice(1);if(phoneScreen()){await applyPhoneRoute(hash||'upload',true);}else if(hash.startsWith('editor/')){await openDoc(hash.slice(7));}else{view=['upload','settings','library'].includes(hash)?hash:'library';render();}clearInterval(pollTimer);pollTimer=setInterval(()=>{if(session.authenticated&&view==='library'&&!document.hidden)run(refresh);},10000);}
boot().catch(e=>{$('app').innerHTML='<div class="loading"><h2>工作台暂时无法打开</h2><p>'+esc(e.message)+'</p><button onclick="location.reload()">重新加载</button></div>';});

document.addEventListener('click',e=>{const row=e.target.closest('[data-file]');if(!row||e.target.closest('button'))return;selectedFile=row.dataset.file;document.querySelectorAll('[data-file]').forEach(el=>el.classList.toggle('selected',el===row));document.querySelector('.finder-detail').innerHTML=libraryDetailHTML(lessons.find(d=>d.id===selectedFile));row.focus({preventScroll:true});});
