document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('[data-file]')){e.preventDefault();(e.target.querySelector('[data-play]')||e.target.querySelector('[data-edit]')).click();}});

document.addEventListener('pointerdown',e=>{const menu=$('library-sort-menu');if(menu?.open&&!menu.contains(e.target))menu.open=false;});
