function collapseEmptySearch(){if(!search&&$('search-toggle')){searchExpanded=false;$('library-search-field').hidden=true;$('search-toggle').setAttribute('aria-expanded','false');}}
document.addEventListener('pointerdown',e=>{if(!e.target.closest('.search-control'))collapseEmptySearch();});
